#: Traversal classes. Every edge type has exactly one; it never changes per edge.
TRAVERSAL_CLASSES: Mapping[str, str] = {
    "control": "Gains the target identity, or code execution as it. A path may continue from the target.",
    "access": "Reaches data or a data gate (read, write, decrypt, administer). Paths end at the target.",
    "exposure": "Reachable from outside (anonymous or another account) without a credential in this account.",
    "structural": "Membership, attachment, placement or an encryption dependency. Never an attack step.",
    "info": "Context: data flow, impact-only actions, incomplete chains. Never an attack step.",
}

#: Edge confidence values (``edge.confidence``).
CONFIDENCE_VALUES: Tuple[str, ...] = ("definite", "conditional")

#: Condition strength values (``evidence.condition_strength``), weakest to strongest gate.
STRENGTH_VALUES: Tuple[str, ...] = ("none", "weak", "strong")

#: Weight penalty added to ``base_weight`` for a conditional edge, by the strongest unresolved gate.
CONDITIONAL_PENALTY: Mapping[str, float] = {"none": 0, "weak": 1, "strong": 3}

#: Prefix of a ``traversable`` value that depends on a per-edge fact (see :data:`TRAVERSABLE_RULES`).
CONDITIONAL_PREFIX = "conditional-on:"

