@dataclass(frozen=True)
class TraversableRule:
    """A per-edge fact that decides whether an edge of a conditionally traversable type may be walked.

    The builder resolves the rule for each edge, writes the boolean into ``edge.traversable`` and records
    ``evidence.traversable_rule = {"rule": name, "holds": bool}``. The edge's traversal class is unchanged.
    """

    name: str
    holds_when: str
    otherwise: str


