# ── Edge types ────────────────────────────────────────────────────────────────

Traversable = Union[bool, str]


@dataclass(frozen=True)
class EdgeType:
    """One row of the traversability table.

    * ``traversable``: ``True``, ``False``, or ``"conditional-on:<rule>"`` (see :data:`TRAVERSABLE_RULES`).
      An edge record always carries a boolean; the builder resolves the rule per edge.
    * ``base_weight``: path cost of a definite edge. ``weight = base_weight + CONDITIONAL_PENALTY[strength]``
      for conditional edges, plus a type-specific ``evidence.weight_extra``; 0 is legal (F-040).
    * ``sources`` / ``targets``: allowed node types, **after** direction normalisation (attacker → asset).
    * ``bridge``: the edge leaves a compute-bridge node towards the identity it runs as.
    * ``legacy_name`` / ``legacy_file`` / ``legacy_reversed`` / ``legacy_category``: how the legacy writer
      renders this type into the d13c215 ``*_relationships.json`` files. ``legacy_reversed`` means the old
      file stored the edge resource → grantee. ``legacy_file_by_source`` overrides ``legacy_file`` per
      source node type. ``legacy_name is None`` means the type is not rendered into legacy files.
    * ``status``: ``"current"`` (the d13c215 engine or dashboard already had it, possibly under another
      name) or ``"new"``.
    """

    name: str
    category: str
    traversal: str
    traversable: Traversable
    base_weight: float
    sources: Tuple[str, ...]
    targets: Tuple[str, ...]
    description: str
    status: str = "current"
    bridge: bool = False
    legacy_name: Optional[str] = None
    legacy_file: Optional[str] = None
    legacy_file_by_source: Tuple[Tuple[str, str], ...] = ()
    legacy_reversed: bool = False
    legacy_category: Optional[str] = None
    findings: Tuple[str, ...] = ()
    doc_anchor: str = field(default="")

    def __post_init__(self) -> None:
        if not self.doc_anchor:
            # Anchor of the heading DOC2 generates from this table: the heading text is the type name.
            object.__setattr__(self, "doc_anchor", "#" + self.name.lower())

    @property
    def traversable_rule(self) -> Optional[str]:
        """The rule name for a conditionally traversable type, else ``None``."""
        if isinstance(self.traversable, str) and self.traversable.startswith(CONDITIONAL_PREFIX):
            return self.traversable[len(CONDITIONAL_PREFIX):]
        return None

    @property
    def may_traverse(self) -> bool:
        """True when some edge of this type can be traversable (always, or when its rule holds)."""
        return self.traversable is True or self.traversable_rule is not None

    def legacy_file_for(self, source_type: Optional[str]) -> Optional[str]:
        """The legacy file an edge with this source node type is rendered into, or ``None``."""
        if self.legacy_name is None:
            return None
        for src, fname in self.legacy_file_by_source:
            if src == source_type:
                return fname
        return self.legacy_file


