def _edges() -> Tuple[EdgeType, ...]:
    """Every edge type, in table order (the order of the rendered page and of the categories' type lists)."""
    return _identity_edges() + _resource_edges() + _data_edges() + _context_edges()


EDGE_TYPES: Mapping[str, EdgeType] = {t.name: t for t in _edges()}


# ── Legacy inventory (d13c215 engine files + old dashboard) ───────────────────

#: Dispositions of a legacy (file, name) pair.
DISPOSITIONS: Mapping[str, str] = {
    "kept": "Same name, same direction.",
    "normalised": "Same name; the stored direction is flipped to grantee → resource.",
    "moved": "Was derived by the dashboard; the engine now emits it.",
    "renamed": "Emitted under a new name.",
    "split": "Divided into several types by action or role kind.",
    "folded": "Merged into other types; the old name is not emitted.",
    "implemented": "Declared (weights or colours) but never emitted before; now emitted.",
    "removed": "No longer emitted; the replacement is listed.",
}


@dataclass(frozen=True)
class LegacyEdge:
    """One legacy (origin, name) pair and what replaced it."""

    origin: str            # a LEGACY_FILES entry, or LEGACY_DASHBOARD
    name: str
    stored: str            # stored direction in d13c215, e.g. "bucket → principal"
    disposition: str
    new_types: Tuple[str, ...]
    note: str = ""


