LEGACY_EDGE_TYPES: Tuple[LegacyEdge, ...] = _legacy()


# ── Weights and registry entries ──────────────────────────────────────────────

def edge_weight(edge_type: str, confidence: str = "definite", strength: str = "none", extra: float = 0) -> float:
    """Normative weight of one emitted edge: base weight, plus the conditional penalty, plus ``extra``."""
    et = EDGE_TYPES[edge_type]
    if confidence not in CONFIDENCE_VALUES:
        raise ValueError(f"confidence must be one of {CONFIDENCE_VALUES}, got {confidence!r}")
    if strength not in STRENGTH_VALUES:
        raise ValueError(f"strength must be one of {STRENGTH_VALUES}, got {strength!r}")
    if extra < 0:
        raise ValueError("extra weight must be >= 0")
    penalty = CONDITIONAL_PENALTY[strength] if confidence == "conditional" else 0
    return _num(et.base_weight + penalty + extra)


def _num(x: float) -> float:
    """Integral floats as ints (``1`` not ``1.0``) so JSON output stays stable."""
    return int(x) if float(x).is_integer() else x


def node_type_entry(name: str) -> Dict[str, object]:
    """The ``graph.json`` ``node_types[name]`` registry entry."""
    t = NODE_TYPES[name]
    return {
        "label": t.label, "icon": t.icon, "group": t.group, "order": t.order,
        "is_compute_bridge": t.is_compute_bridge, "default_source": t.default_source,
        "data_asset": t.data_asset, "synthetic": t.synthetic, "description": t.description,
    }


def edge_type_entry(name: str) -> Dict[str, object]:
    """The ``graph.json`` ``edge_types[name]`` registry entry."""
    t = EDGE_TYPES[name]
    cat = CATEGORIES[t.category]
    return {
        "category": t.category, "category_label": cat.label, "category_order": cat.order,
        "traversal": t.traversal,
        "traversable": "conditional" if t.traversable_rule else t.traversable,
        "traversable_rule": t.traversable_rule,
        "base_weight": _num(t.base_weight), "bridge": t.bridge,
        "sources": list(t.sources), "targets": list(t.targets),
        "description": t.description, "doc_anchor": t.doc_anchor, "legacy_name": t.legacy_name,
    }


def registries_for(node_types: Iterable[str], edge_types: Iterable[str]) -> Tuple[dict, dict]:
    """``(node_types, edge_types)`` registry blocks for the given type names, keys sorted."""
    return (
        {n: node_type_entry(n) for n in sorted(set(node_types))},
        {e: edge_type_entry(e) for e in sorted(set(edge_types))},
    )


# ── Self-check ────────────────────────────────────────────────────────────────

def check_table() -> List[str]:
    """Internal consistency of the table. Returns a list of problems (empty when consistent)."""
    problems: List[str] = []
    for name, nt in NODE_TYPES.items():
        if nt.group not in NODE_GROUPS:
            problems.append(f"node type {name}: unknown group {nt.group!r}")
        if not name.replace("_", "").isalnum() or name != name.lower():
            problems.append(f"node type {name}: name must be lower-case [a-z0-9_]")
    orders = [nt.order for nt in NODE_TYPES.values()]
    if sorted(orders) != list(range(1, len(orders) + 1)):
        problems.append("node type orders must be 1..N without gaps")
    for name, et in EDGE_TYPES.items():
        where = f"edge type {name}"
        if et.category not in CATEGORIES:
            problems.append(f"{where}: unknown category {et.category!r}")
        if et.traversal not in TRAVERSAL_CLASSES:
            problems.append(f"{where}: unknown traversal class {et.traversal!r}")
        if not (et.traversable is True or et.traversable is False or et.traversable_rule in TRAVERSABLE_RULES):
            problems.append(f"{where}: traversable must be True, False or conditional-on:<known rule>")
        if et.traversable_rule and et.traversal != "control":
            problems.append(f"{where}: only control types may be conditionally traversable")
        if et.traversal in ("structural", "info") and et.traversable is not False:
            problems.append(f"{where}: {et.traversal} edges are never traversable")
        if not (isinstance(et.base_weight, (int, float)) and et.base_weight >= 0):
            problems.append(f"{where}: base_weight must be a number >= 0")
        if et.status not in ("current", "new"):
            problems.append(f"{where}: status must be current or new")
        for nt in et.sources + et.targets:
            if nt not in NODE_TYPES:
                problems.append(f"{where}: unknown node type {nt!r}")
        if len(set(et.sources)) != len(et.sources) or len(set(et.targets)) != len(et.targets):
            problems.append(f"{where}: duplicate node types in sources/targets")
        if et.may_traverse:
            # bridge invariant: a compute node is entered only through control edges (F-004)
            for t in et.targets:
                if t in NODE_TYPES and NODE_TYPES[t].is_compute_bridge and et.traversal != "control":
                    problems.append(f"{where}: traversable {et.traversal} edge into compute bridge {t}")
            # data assets are terminal
            for s in et.sources:
                if s in NODE_TYPES and NODE_TYPES[s].data_asset:
                    problems.append(f"{where}: traversable edge leaves data asset {s}")
        if et.bridge:
            if et.traversal != "control":
                problems.append(f"{where}: bridge edges must be control")
            if not all(NODE_TYPES[s].is_compute_bridge for s in et.sources if s in NODE_TYPES):
                problems.append(f"{where}: bridge edges must leave compute-bridge node types")
        if et.legacy_name is not None:
            files = {et.legacy_file} | {f for _, f in et.legacy_file_by_source}
            if not files or not files <= set(LEGACY_FILES):
                problems.append(f"{where}: legacy files {sorted(map(str, files))} not in LEGACY_FILES")
            if et.legacy_category is None:
                problems.append(f"{where}: legacy_category required with legacy_file")
        elif et.legacy_file or et.legacy_file_by_source or et.legacy_reversed or et.legacy_category:
            problems.append(f"{where}: legacy_* fields set without legacy_name")
        if et.doc_anchor != "#" + name.lower():
            problems.append(f"{where}: doc_anchor must be #{name.lower()}")
        for fid in et.findings:
            if not (fid.startswith("F-") and fid[2:].isdigit() and len(fid) == 5):
                problems.append(f"{where}: bad finding id {fid!r}")
    seen = set()
    for le in LEGACY_EDGE_TYPES:
        key = (le.origin, le.name)
        if key in seen:
            problems.append(f"legacy {key}: duplicate")
        seen.add(key)
        if le.origin not in LEGACY_FILES and le.origin != LEGACY_DASHBOARD:
            problems.append(f"legacy {key}: unknown origin")
        if le.disposition not in DISPOSITIONS:
            problems.append(f"legacy {key}: unknown disposition {le.disposition!r}")
        if not le.new_types:
            problems.append(f"legacy {key}: new_types must name at least one replacement")
        for nt in le.new_types:
            if nt not in EDGE_TYPES:
                problems.append(f"legacy {key}: unknown new type {nt!r}")
        if le.disposition == "kept" and le.new_types != (le.name,):
            problems.append(f"legacy {key}: kept means new_types == (name,)")
        if le.disposition in ("renamed", "folded", "removed") and le.name in le.new_types and le.origin != \
                LEGACY_DASHBOARD:
            problems.append(f"legacy {key}: {le.disposition} must not list the old name as a new type")
    return problems


# ── Markdown rendering (docs/contracts/traversability-table.md) ──────────────

def _md(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def _w(x: float) -> str:
    return str(_num(x))


def _t(et: EdgeType) -> str:
    if et.traversable is True:
        return "T"
    if et.traversable is False:
        return "F"
    return f"T if `{et.traversable_rule}`"


def _legacy_cell(et: EdgeType) -> str:
    if et.legacy_name is None:
        return "—"
    files = [et.legacy_file] + [f"{f} (from {s})" for s, f in et.legacy_file_by_source]
    rev = ", reversed" if et.legacy_reversed else ""
    return f"`{et.legacy_name}` in {', '.join(str(f) for f in files)}{rev}"


def _md_rules(a: Callable[[str], None]) -> None:
    """Header and the rules every consumer applies (§1)."""
    a("<!-- GENERATED by aws_enumerator.engine.graph.edge_types.render_markdown(); do not edit by hand. -->")
    a("<!-- Regenerate: .venv/bin/python -m aws_enumerator.engine.graph.edge_types --write "
      "docs/contracts/traversability-table.md -->")
    a("")
    a("# Traversability table (graph contract 1.0)")
    a("")
    a("**Status:** frozen contract (Wave 0, stream contracts-engine; Wave 3 additions by I1: "
      "`PARAM_GRANTS_CROSS_ACCOUNT`, `AMI_SHARED_CROSS_ACCOUNT`, `SSMDOC_SHARED_CROSS_ACCOUNT`, "
      "`LAYER_GRANTS_CROSS_ACCOUNT` and `VPC_CONNECTED`, DECISIONS.md D-52). The single source is "
      "`aws_enumerator/engine/graph/edge_types.py`; this page is generated from it and a test fails when they "
      "differ. New types are table additions within graph schema 1.0 (graph-json.md §14). Change it only through "
      "a change request.")
    a("")
    a(f"{len(EDGE_TYPES)} edge types, {len(NODE_TYPES)} node types, {len(CATEGORIES)} categories, "
      f"{len(LEGACY_EDGE_TYPES)} legacy (origin, name) pairs.")
    a("")
    a("## 1. Rules every consumer applies")
    a("")
    a("1. **Direction.** Every edge is stored in the attack direction: whoever controls the source gains the "
      "capability on the target. Grants found in resource policies (bucket, key, secret, function, queue, "
      "topic, table, repository and snapshot policies or sharing lists) are **normalised** to "
      "grantee → resource. Public grants start at the synthetic node `aws-enumerator:anonymous`. The old "
      "resource → grantee direction survives only in the legacy files (`legacy_reversed`).")
    a("2. **Traversal.** A path walks only edges whose record has `traversable: true`, and only from `source` "
      "to `target`. Weights are summed as stored; `0` is a real cost of zero (F-040). Implementations must "
      "pass the shared vectors in `tests/fixtures/graph/path_cases.json`.")
    a("3. **Class is per type.** `traversal` never changes per edge. What varies per edge is `traversable` "
      "(conditional rules, bridge demotion) and `weight` (confidence penalty).")
    a("4. **Weight.** `weight = base_weight + penalty + evidence.weight_extra`, where the penalty is "
      + ", ".join(f"{k} = {_w(v)}" for k, v in CONDITIONAL_PENALTY.items())
      + " by `evidence.condition_strength` for a conditional edge, and 0 for a definite edge. "
        "When two emissions merge on (source, type, target) the weight is the minimum and the confidence the "
        "more definite. A weight is always a finite number ≥ base_weight ≥ 0.")
    a("5. **Bridge invariant (F-004).** A node whose type has `is_compute_bridge` runs code as an identity. "
      "Every traversable edge **into** it must be of class `control`. The builder demotes any other incoming "
      "edge to `traversable: false` with `evidence.demoted_by = \"bridge-invariant\"`; the table below already "
      "satisfies the invariant, so a demotion means an analyzer emitted something the table does not allow.")
    a("6. **Data assets are terminal.** No traversable edge leaves a node whose type has `data_asset`. ACCESS "
      "edges therefore end a path.")
    a("7. **Endpoints.** Source and target node types must be in the row's `sources` / `targets` lists. No "
      "node id starts with `principal:` (the old `principal:*` placeholder is gone).")
    a("")


def _md_vocabularies(a: Callable[[str], None]) -> None:
    """Traversal classes, conditional rules and categories (§2-§4)."""
    a("## 2. Traversal classes")
    a("")
    a("| Class | Meaning |")
    a("|---|---|")
    for k, v in TRAVERSAL_CLASSES.items():
        a(f"| `{k}` | {_md(v)} |")
    a("")
    a("## 3. Conditional traversability rules")
    a("")
    a("A type with `traversable = conditional-on:<rule>` is emitted with a boolean decided per edge; the "
      "builder records `evidence.traversable_rule = {\"rule\": <rule>, \"holds\": <bool>}`.")
    a("")
    a("| Rule | Traversable when | Otherwise | Types |")
    a("|---|---|---|---|")
    for r in TRAVERSABLE_RULES.values():
        types = ", ".join(f"`{e.name}`" for e in EDGE_TYPES.values() if e.traversable_rule == r.name)
        a(f"| `{r.name}` | {_md(r.holds_when)} | {_md(r.otherwise)} | {types} |")
    a("")
    a("## 4. Categories")
    a("")
    a("| Order | Category | Label | Edge types |")
    a("|---|---|---|---|")
    for c in sorted(CATEGORIES.values(), key=lambda c: c.order):
        names = ", ".join(f"`{e.name}`" for e in EDGE_TYPES.values() if e.category == c.name)
        a(f"| {c.order} | `{c.name}` | {_md(c.label)} | {names} |")
    a("")


def _md_edge_types(a: Callable[[str], None]) -> None:
    """One table per category (§5)."""
    a("## 5. Edge types")
    a("")
    a("T = traversable, F = not traversable, w = base weight. Sources and targets are node types after "
      "normalisation. \"Bridge\" marks compute → identity edges.")
    a("")
    for c in sorted(CATEGORIES.values(), key=lambda c: c.order):
        a(f"### 5.{c.order} {c.label} (`{c.name}`)")
        a("")
        a("| Edge type | Class | T | w | Sources → targets | Status | Legacy rendering | Meaning |")
        a("|---|---|---|---|---|---|---|---|")
        for e in EDGE_TYPES.values():
            if e.category != c.name:
                continue
            bridge = " (bridge)" if e.bridge else ""
            ends = f"{', '.join(e.sources)} → {', '.join(e.targets)}"
            fids = f" ({', '.join(e.findings)})" if e.findings else ""
            a(f"| `{e.name}` | {e.traversal}{bridge} | {_t(e)} | {_w(e.base_weight)} | {_md(ends)} | {e.status} "
              f"| {_md(_legacy_cell(e))} | {_md(e.description)}{fids} |")
        a("")


def _md_nodes_and_legacy(a: Callable[[str], None]) -> None:
    """Node types and the d13c215 legacy inventory (§6-§7)."""
    a("## 6. Node types")
    a("")
    a("`order` drives selector sorting (starts at 1). `entry` = default source (`props.entry_point`), "
      "`bridge` = compute bridge, `data` = data asset.")
    a("")
    a("| Order | Type | Label | Group | Icon | Flags | Notes |")
    a("|---|---|---|---|---|---|---|")
    for t in sorted(NODE_TYPES.values(), key=lambda t: t.order):
        flags = [f for f, on in (("entry", t.default_source), ("bridge", t.is_compute_bridge),
                                 ("data", t.data_asset), ("synthetic", t.synthetic)) if on]
        a(f"| {t.order} | `{t.name}` | {_md(t.label)} | {t.group} | `{t.icon}` | {', '.join(flags) or '—'} "
          f"| {_md(t.description) or '—'} |")
    a("")
    a("New icon keys the dashboard stream must add (until then it falls back to `generic`): "
      + ", ".join(f"`{k}`" for k in NEW_ICON_KEYS) + ".")
    a("")
    a("## 7. Legacy inventory (d13c215)")
    a("")
    a("Every edge name the d13c215 engine emitted or declared, and every edge the old dashboard derived, "
      "with what replaces it. A test checks this list against the d13c215 weight tables and the legacy "
      "goldens. The table documents the old vocabulary; the engine no longer imports d13c215 analyzer output "
      "(the legacy adapter was removed in Wave 3, D-53).")
    a("")
    a("| Origin | Legacy name | Stored as | Disposition | New types | Note |")
    a("|---|---|---|---|---|---|")
    for le in LEGACY_EDGE_TYPES:
        a(f"| {le.origin} | `{le.name}` | {_md(le.stored)} | {le.disposition} | "
          f"{', '.join(f'`{n}`' for n in le.new_types)} | {_md(le.note) or '—'} |")
    a("")
    a("| Disposition | Meaning |")
    a("|---|---|")
    for k, v in DISPOSITIONS.items():
        a(f"| {k} | {_md(v)} |")
    a("")
    a("The legacy writer renders an edge into `legacy_file_for(source type)` under `legacy_name`, flipping "
      "source and target when `legacy_reversed`, with `category = legacy_category`. Types without a "
      "`legacy_name` are not rendered. The chronological names `newsurface_relationships.json` (ECR, RDS, API "
      "Gateway, DynamoDB) and `extra_relationships.json` (EBS, ELB, Route 53, Cognito) survive only as these "
      "legacy output file names (graph-json.md §1, D-22); the domain-neutral document is `graph.json` and no "
      "alias files are written (F-164).")
    a("")



def render_markdown() -> str:
    """Render ``docs/contracts/traversability-table.md`` from the table. Deterministic."""
    out: List[str] = []
    a = out.append
    for section in (_md_rules, _md_vocabularies, _md_edge_types, _md_nodes_and_legacy):
        section(a)
    return "\n".join(out)


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    text = render_markdown()
    if len(args) == 2 and args[0] in ("--write", "--check"):
        if args[0] == "--write":
            with open(args[1], "w", encoding="utf-8", newline="\n") as fh:
                fh.write(text)
            return 0
        with open(args[1], encoding="utf-8") as fh:
            return 0 if fh.read() == text else 1
    if args:
        sys.stderr.write("usage: edge_types.py [--write PATH | --check PATH]\n")
        return 64
    problems = check_table()
    for p in problems:
        sys.stderr.write(p + "\n")
    sys.stdout.write(text)
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())
